use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fmt::Write,fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-wide-top176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-g2-wide-top176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,v)}else{v.push(p)}}}
fn main(){let r=Path::new(R);let d=Path::new(D);assert!(!d.join("artifacts/final-publication-review.json").exists());assert_eq!(read(d.join("artifacts/publication-review.json"))["passed"],true);assert_eq!(read(d.join("artifacts/diagnostic-qualification.json"))["passed"],true);let mut closed=BTreeMap::new();
 for group in["source","workflow","receipts","codegen"]{let base=r.join("archive-review").join(group);let mut files=vec![];walk(&base,&mut files);for p in&files{assert_eq!(hash(p),hash(r.join(p.strip_prefix(&base).unwrap())));}closed.insert(group,files.len());}
 let base=r.join("supplement-review");let mut files=vec![];walk(&base,&mut files);for p in&files{assert_eq!(hash(p),hash(r.join(p.strip_prefix(&base).unwrap())));}closed.insert("preparation-supplement",files.len());
 let a=read(r.join("analysis.json"));for(name,v)in a["cases"].as_object().unwrap(){if name.contains("-B-"){assert_eq!(v["candidate_over_control"]["wins"],0);assert_eq!(v["candidate_over_frozen"]["wins"],0);}}
 let text=fs::read_to_string(d.join("README.md")).unwrap();let mut links=vec![];for x in text.split("](").skip(1){let t=x.split(')').next().unwrap();if !t.starts_with("http"){assert!(d.join(t).is_file(),"{t}");}links.push(t.to_owned());}assert!(!text.contains("true/null"));
 for(src,dest)in[("polish.rs","editorial.rs"),("verify-publication.rs","verify-publication.rs")]{fs::copy(r.join(src),d.join("artifacts").join(dest)).unwrap();}
 let v=json!({"passed":true,"all_five_archive_member_sets_byte_exact":closed,"README_links_checked":links.len(),"README_sha256":hash(d.join("README.md")),"raw_analysis_sha256":hash(r.join("analysis.json")),"independent_review_sha256":hash(r.join("review.json")),"all_six_B_cases_zero_wins_against_both_controls":true,"publisher_and_capture_sources_unchanged":true,"editorial_only_after_initial_publication":true,"goal_active_0_of_8":true,"new_proofs":0});fs::write(d.join("artifacts/final-publication-review.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();let mut files=vec![];walk(d,&mut files);files.sort();let mut sums=String::new();for p in files{if p.file_name().unwrap()=="SHA256SUMS"{continue}writeln!(sums,"{}  {}",hash(&p),p.strip_prefix(d).unwrap().display()).unwrap();}fs::write(d.join("SHA256SUMS"),sums).unwrap();println!("{v}");}
